 for(const x of [-.17,.17])body.add(box(.13,.012,.72,black,x,.87,-1.22));body.add(box(1.8,.16,.1,black,0,.48,-2.17));body.add(box(1.7,.16,.1,black,0,.47,2.19));body.add(box(1.38,.075,.05,red,0,.75,2.24));
 body.add(box(1.72,.06,.39,black,0,.93,1.96));for(const x of [-.65,.65])body.add(box(.06,.22,.08,black,x,.84,1.91));
 body.add(box(.7,.2,.03,white,0,.59,2.255));
 // License plate lettering is original, generated locally.
 const plate=document.createElement('canvas');plate.width=256;plate.height=64;const pc=plate.getContext('2d');pc.fillStyle='#e9efdc';pc.fillRect(0,0,256,64);pc.fillStyle='#18252e';pc.font='bold 35px monospace';pc.textAlign='center';pc.fillText('B · MID 01',128,45);const pt=new T.CanvasTexture(plate);body.add(mesh(new T.PlaneGeometry(.62,.15),new T.MeshBasicMaterial({map:pt}),0,.59,2.276));
 const front=[],wheels=[];
